<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { Plus, Trash2 } from 'lucide-vue-next'; import ModalDialog from '@/components/ModalDialog.vue'; import EmptyState from '@/components/EmptyState.vue'; import { api } from '@/services/api'; import { errorMessage } from '@/services/http'; import type { Passenger } from '@/types'
const items=ref<Passenger[]>([]);const open=ref(false);const message=ref('');const form=reactive({name:'',idType:'ID_CARD',idNo:'',phone:''});async function load(){items.value=await api.passengers()}async function add(){try{await api.addPassenger(form);open.value=false;Object.assign(form,{name:'',idType:'ID_CARD',idNo:'',phone:''});await load()}catch(e){message.value=errorMessage(e)}}async function remove(id:string){if(!confirm('确认删除这位乘车人吗？'))return;try{await api.deletePassenger(id);await load()}catch(e){message.value=errorMessage(e)}}onMounted(load)
</script>
<template><section class="page container"><header class="page-head"><div><p class="eyebrow">PASSENGERS</p><h1>常用乘车人</h1><p>购票前请先维护乘车人实名信息</p></div><button class="btn primary" @click="open=true"><Plus/>添加乘车人</button></header><p v-if="message" class="notice error">{{message}}</p><div v-if="items.length" class="passenger-grid"><article v-for="item in items" :key="item.id" class="info-card"><div class="avatar">{{item.name.slice(-1)}}</div><div><h3>{{item.name}}</h3><p>{{item.idType==='ID_CARD'?'居民身份证':item.idType}} · {{item.idNo}}</p><small>{{item.phone}}</small></div><button class="icon-btn danger" @click="remove(item.id)"><Trash2/></button></article></div><EmptyState v-else title="还没有常用乘车人" hint="添加后即可为本人或亲友购票"/><ModalDialog :open="open" title="添加乘车人" @close="open=false"><form class="stack-form" @submit.prevent="add"><label>姓名<input v-model.trim="form.name" required></label><label>证件类型<select v-model="form.idType"><option value="ID_CARD">居民身份证</option></select></label><label>证件号码<input v-model.trim="form.idNo" required></label><label>手机号<input v-model.trim="form.phone" required pattern="1[3-9][0-9]{9}"></label><button class="btn primary wide">保存乘车人</button></form></ModalDialog></section></template>
